package net.emeraldsmp.anticheat;
import net.emeraldsmp.EmeraldSMP;import org.bukkit.Material;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.Action;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.event.player.*;import java.util.*;
public final class MacroAntiCheat implements Listener{private final EmeraldSMP plugin;private final Map<UUID,State> states=new HashMap<>();public MacroAntiCheat(EmeraldSMP p){plugin=p;}
 @EventHandler public void interact(PlayerInteractEvent e){if(e.getAction()!=Action.LEFT_CLICK_BLOCK&&e.getAction()!=Action.RIGHT_CLICK_BLOCK&&e.getAction()!=Action.LEFT_CLICK_AIR&&e.getAction()!=Action.RIGHT_CLICK_AIR)return;Player p=e.getPlayer();if(!plugin.getAuthManager().isAntiCheatReady(p)||p.hasPermission("emerald.anticheat.bypass"))return;Material m=e.getClickedBlock()==null?p.getInventory().getItemInMainHand().getType():e.getClickedBlock().getType();observe(p,e.getAction()+":"+m.name());}
 @EventHandler public void inventory(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!plugin.getAuthManager().isAntiCheatReady(p)||p.hasPermission("emerald.anticheat.bypass"))return;observe(p,"INV:"+e.getClick()+":"+e.getRawSlot());}
 private void observe(Player p,String key){long now=System.nanoTime();State s=states.computeIfAbsent(p.getUniqueId(),x->new State());if(!key.equals(s.key)){s.reset(key,now);return;}long dt=now-s.last;if(dt<40_000_000L||dt>300_000_000L){s.reset(key,now);return;}s.last=now;s.intervals.add(dt);if(s.intervals.size()>20)s.intervals.remove(0);if(s.intervals.size()>=12&&identical(s.intervals)){s.suspicion++;if(s.suspicion>=3)plugin.getSusListManager().record(p,p.getLocation(),"Macro",s.suspicion,Math.min(100,20+s.suspicion*5));}else s.suspicion=Math.max(0,s.suspicion-1);}
 private boolean identical(List<Long>x){return Collections.max(x)-Collections.min(x)<=4_000_000L;}@EventHandler public void quit(PlayerQuitEvent e){states.remove(e.getPlayer().getUniqueId());}
 private static final class State{String key;long last;int suspicion;List<Long> intervals=new ArrayList<>();void reset(String k,long n){key=k;last=n;suspicion=Math.max(0,suspicion-1);intervals.clear();}}
}